<script>let {titulo='Confirmar acción',detalle='',cancelar=()=>{},confirmar=()=>{},ocupado=false}=$props();</script>
<div class="fondo" role="presentation"><div class="dialogo" role="dialog" aria-modal="true" aria-label={titulo}><h2>{titulo}</h2><p>{detalle}</p><div class="botones"><button class="cancelar" onclick={cancelar} disabled={ocupado}>Cancelar</button><button class="peligro" onclick={confirmar} disabled={ocupado}>{ocupado?'Procesando…':'Confirmar'}</button></div></div></div>
<style>.fondo{position:fixed;inset:0;z-index:1000;background:#0f172a99;display:grid;place-items:center;padding:15px}.dialogo{max-width:450px;width:100%;background:white;border-radius:14px;padding:26px;box-shadow:0 20px 60px #0004}.dialogo h2{color:#1e3a8a}.dialogo p{line-height:1.5}.botones{display:flex;justify-content:flex-end;gap:10px}button{border:0;border-radius:8px;padding:11px 16px;cursor:pointer}.cancelar{background:#e2e8f0}.peligro{background:#b91c1c;color:white}</style>
